mapper.select:
SELECT a.id, a.issue_id, a.user_id, a.action, a.field_name, , a.created_at, u.display_name AS user_name, i.issue_key, i.title AS issue_title FROM issue_activity a LEFT JOIN sys_user u ON u.id = a.user_id LEFT JOIN issue i ON i.id = a.issue_id
WHERE a.issue_id IN
#{id}
ORDER BY a.created_at DESC LIMIT #{limit}
